    idioma: Literal["es-MX", "en"]
    semilla: Annotated[int, Field(ge=0, le=4294967295)]
    """
    Semilla de toda aleatoriedad (Monte Carlo, ragdolls, variación visual). Misma escena + misma semilla ⇒ misma reconstrucción.
    """
    creado: AwareDatetime
    titulo: Annotated[str | None, Field(max_length=120)] = None
    hash_relato: Annotated[str | None, Field(pattern="^[0-9a-f]{64}$")] = None
    """
    SHA-256 del relato normalizado. El texto completo solo vive en el dispositivo salvo consentimiento.
    """
    relato: Annotated[str | None, Field(max_length=20000)] = None
    """
    Texto del relato con PII ya redactada. Opcional; solo presente en el dispositivo o con consentimiento.
    """
    origen_relato: Literal["escrito", "voz", "precargado", "manual"] | None = None
    sintetico: bool | None = None
